input.old_string:
pattern = r'([+-]?\d+)'
if range_delim:
    pattern += r'\s*' + re.escape(range_delim) + r'\s*([+-]?\d+)'
return re.compile(pattern + r'\Z')

input.new_string:
pattern = r'([+-]?\d+)'
if range_delim:
    pattern += r'(?:\s*' + re.escape(range_delim) + r'\s*([+-]?\d+))?'
return re.compile(pattern + r'\Z')
